<?php /** @var array $category @var array $items @var string $basePath @var string $assetBase */ ?>
<section class="c-page-title"><a href="<?= e_attr($basePath) ?>/menus">← All menus</a><p class="c-eyebrow">Catering menu</p><h1><?= e($category['name']) ?></h1><p><?= e($category['description']) ?></p></section>
<section class="c-wrap c-section c-menu-detail"><div class="c-menu-detail-list"><?php foreach ($items as $item): ?><article><?php if (!empty($item['image'])): ?><img class="c-menu-detail-photo" src="<?= e_attr($assetBase . '/assets/images/menu/' . rawurlencode((string) $item['image'])) ?>" alt="<?= e_attr($item['name']) ?>" loading="lazy" width="1200" height="800"><?php endif; ?><div class="c-menu-item-copy"><h2><?= e($item['name']) ?></h2><p><?= e($item['description']) ?></p><?php if ($item['dietary'] !== ''): ?><div class="c-chips"><?php foreach (explode(',', (string) $item['dietary']) as $tag): ?><span><?= e(trim($tag)) ?></span><?php endforeach; ?></div><?php endif; ?><p class="c-menu-price">$<?= e(number_format(((int) $item['price_cents']) / 100, 2)) ?><small><?= e($item['price_unit']) ?></small></p></div></article><?php endforeach; ?></div><aside><p class="c-eyebrow">Make it yours</p><h2>Build this menu into your event.</h2><p>Tell us your date, guest count, service style, and favorite selections.</p><a class="c-button c-button-green" href="<?= e_attr($basePath . '/request-a-quote?menu_interest=' . rawurlencode((string) $category['name'])) ?>">Request a proposal</a></aside></section>
